let sensors=$("#sensors");let sensor=$("#sensor");let sensorIds=sensors.data("sensors");function displayFloat(value){if(value!==0){return(Math.round(value*10)/10).toFixed(1)}else{return"N/B"}}function displayPMDate(date,value){if(value===0){return""}else{return date+": "}}sensorsArray=[];sensorIds.forEach(index=>{let dates=$("#sensor-"+index+"-timestamp").data("timestamp");let temperatures=$("#sensor-"+index+"-temperature").data("temperature");let humidities=$("#sensor-"+index+"-humidity").data("humidity");let pm25s=$("#sensor-"+index+"-pm25").data("pm25");let pm10s=$("#sensor-"+index+"-pm10").data("pm10");let date=dates[dates.length-1];date=new Date(date+" AM UTC").toLocaleString();let temperature=temperatures[temperatures.length-1];let humidity=humidities[humidities.length-1];let pm25=pm25s[pm25s.length-1];let pm10=pm10s[pm10s.length-1];let sensor=new ol.Feature({geometry:new ol.geom.Point(ol.proj.fromLonLat(toMeanLonLat(index))),id:index,name:'<p class="sensor-title">Sensor '+index+"</p>"+'<p class="text-nowrap">'+date+": Temperatuur "+displayFloat(temperature)+"</p>"+'<p class="text-nowrap">'+date+": RV "+displayFloat(humidity)+"</p>"+'<p class="text-nowrap">'+displayPMDate(date,pm25)+"Fijnstof 2.5 "+displayFloat(pm25)+"</p>"+'<p class="text-nowrap">'+displayPMDate(date,pm10)+"Fijnstof 10 "+displayFloat(pm10)+"</p>"});sensor.setStyle(new ol.style.Style({image:new ol.style.Icon({crossOrigin:"anonymous",src:"/static/img/sensor-blue.png",width:30,height:30})}));sensorsArray.push(sensor)});const vectorSource=new ol.source.Vector({features:sensorsArray});const vectorLayer=new ol.layer.Vector({source:vectorSource});const map=new ol.Map({layers:[new ol.layer.Tile({source:new ol.source.OSM}),vectorLayer],target:document.getElementById("map"),view:new ol.View({center:ol.proj.fromLonLat([5.085,52.085]),zoom:12.5})});const element=document.getElementById("popup");const popup=new ol.Overlay({element:element,positioning:"bottom-center",stopEvent:false});map.addOverlay(popup);let popover;function disposePopover(){if(popover){popover.dispose();popover=undefined}}map.on("click",function(evt){if(popupIcon(evt)){sensor.val()}});map.on("pointermove",function(e){const hit=map.hasFeatureAtPixel(e.pixel);map.getTargetElement().style.cursor=hit?"pointer":""});map.on("movestart",disposePopover);function popupIcon(evt){let feature;if(typeof evt==="object"){feature=map.forEachFeatureAtPixel(evt.pixel,function(feature){return feature})}else{feature=sensorsArray[sensorIds.indexOf(evt)]}disposePopover();if(!feature){return 0}if(typeof evt==="object"){popup.setPosition(evt.coordinate)}else{popup.setPosition(ol.proj.fromLonLat(toMeanLonLat(evt)))}popover=new bootstrap.Popover(element,{placement:"top",html:true,content:feature.get("name")});popover.show();if(typeof evt==="object"){sensor.val(feature.get("id"));graph()}return evt}function toMeanLonLat(id){let longitudes=$("#sensor-"+id+"-longitude").data("longitude");let latitudes=$("#sensor-"+id+"-latitude").data("latitude");let total=0;let count=0;for(let i=0;i<longitudes.length;i++){if(longitudes[i]!==null){total+=longitudes[i];count++}}let longitude=total/count;total=0;count=0;for(let i=0;i<latitudes.length;i++){if(latitudes[i]!==null){total+=latitudes[i];count++}}let latitude=total/count;return[longitude,latitude]}function graph(){google.charts.load("current",{packages:["corechart"]});google.charts.setOnLoadCallback(function(){drawChart()})}function drawChart(){let id=sensor.val();let vertical="y";let horizontal="t";let horizontalData=[0];let verticalData=[0];let type=$("input[name=type]:checked").val();let title="Grafiek";if(id!==""){let rawData=$("#sensor-"+id+"-timestamp").data("timestamp");horizontalData=[];rawData.forEach(function(element){let date=new Date(element).toLocaleString();horizontalData.push(date)});if(type==="temperature"){title="Temperatuur";vertical="°C";verticalData=$("#sensor-"+id+"-temperature").data("temperature")}else if(type==="humidity"){title="Luchtvochtigheid";vertical="RV %";verticalData=$("#sensor-"+id+"-humidity").data("humidity")}else if(type==="pm25"){title="Fijnstof 2.5 µm";vertical="µg/m3";verticalData=$("#sensor-"+id+"-pm25").data("pm25")}else if(type==="pm10"){title="Fijnstof 10 µm";vertical="µg/m3";verticalData=$("#sensor-"+id+"-pm10").data("pm10")}}let indices=[];verticalData.forEach(function(element,index){if(element===null){indices.push(index)}});for(var i=indices.length-1;i>=0;i--){horizontalData.splice(indices[i],1);verticalData.splice(indices[i],1)}if(horizontalData.length===0||verticalData.length===0){verticalData=[0];horizontalData=[0]}let dataGraph=horizontalData.map((name,index)=>[name,verticalData[index]]);let data=google.visualization.arrayToDataTable([[horizontal,vertical]].concat(dataGraph));let options={title:title,curveType:"function",vAxis:{title:vertical},hAxis:{title:horizontal},legend:{position:"none"}};let chart=new google.visualization.LineChart(document.getElementById("curve_chart"));chart.draw(data,options)}graph();sensor.on("change",function(){popupIcon($(this).val());graph()});$("input[name=type]").on("change",function(){graph()});